-- Re-siembra idempotente del tenant iStore de Dario (cmtz36…).
-- Las migraciones originales usaban el guard "si el tenant no existe, salir":
-- cuando corrieron antes de que la tienda existiera en producción quedaron
-- marcadas como aplicadas pero sin datos (Prisma no las vuelve a ejecutar).
-- Esta migración re-ejecuta TODO el seed (catálogo, stock, ubicaciones,
-- usuarios, clientes, órdenes, pagos y precios de lista) solo cuando el
-- tenant existe y no tiene ninguna orden. Todos los INSERT usan
-- ON CONFLICT DO NOTHING: converge al estado completo sin duplicar lo
-- que ya estaba sembrado, y no hace nada si las órdenes ya existen.

DO $$
DECLARE
  v_tenant_id TEXT;
  v_branch_id TEXT;
  v_location_id TEXT;
  v_count INTEGER := 0;
  v_ordenes INTEGER;
BEGIN
  SELECT id INTO v_tenant_id FROM "Tenant" WHERE id = 'cmtz36apy00002ephu1gv7tkt' ORDER BY "createdAt" LIMIT 1;
  IF v_tenant_id IS NULL THEN RETURN; END IF;
  SELECT count(*) INTO v_ordenes FROM "Order" WHERE "tenantId" = v_tenant_id;
  IF v_ordenes > 0 THEN RETURN; END IF;

-- ── 20260916090000_istore_seed_cmtz36 ─────────────────────────────────────────────
SELECT id INTO v_branch_id FROM "Branch" WHERE "tenantId" = v_tenant_id AND "isActive" = true ORDER BY ((lower(name) LIKE '%asu%') OR (lower(name) LIKE '%asunc%')) DESC, "createdAt" LIMIT 1;
