  -- Stock: todo producto con unidades refleja las disponibles/reservadas;
  -- los de cantidad (sin serie) se descuentan una sola vez.
  UPDATE "Product" p SET "stock" = COALESCE((SELECT count(*) FROM "InventoryUnit" u WHERE u."productId" = p."id" AND u."status" IN ('AVAILABLE', 'RESERVED')), 0) WHERE p."tenantId" = v_tenant_id AND p."branchId" = v_branch_id AND EXISTS (SELECT 1 FROM "InventoryUnit" u2 WHERE u2."productId" = p."id");
